#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

typedef struct Node { int value; struct Node *next; } Node;
static int prepend(Node **head,int value){
    Node *node=malloc(sizeof *node);if(!node)return 0;
    *node=(Node){value,*head};*head=node;return 1;
}
static void remove_value(Node **head,int target){
    /* link указывает на поле, которое владеет ссылкой на текущий узел. */
    Node **link=head;
    while(*link){
        if((*link)->value==target){Node *old=*link;*link=old->next;free(old);}
        else link=&(*link)->next;
    }
}
static void destroy(Node **head){
    while(*head){Node *old=*head;*head=old->next;free(old);}
}
int main(void) {
int a[256]; int n;
if (scanf("%d", &n)!=1 || n<0 || n>256) return 1;
for(int i=0;i<n;++i) if(scanf("%d", &a[i])!=1) return 1;
int target;if(scanf("%d",&target)!=1)return 1;Node *head=NULL;for(int i=n;i>0;--i)if(!prepend(&head,a[i-1])){destroy(&head);return 1;}remove_value(&head,target);int first=1;for(Node *node=head;node;node=node->next){printf("%s%d",first?"":" ",node->value);first=0;}puts("");destroy(&head);
return 0;
}
